Function:
public class NormalizeLongitude {
public static double normalizeLongitude(double in)
    {
        double out = in;
        if (out > 180.)
        {
            out -= (int)((out + 180.) / 360.) * 360.;
        }
        else if (out < -180.)
        {
            out -= (int)((out - 180.) / 360.) * 360.;
        }
        // Allow both 180 and -180.

        return out;
    }
}

