        Assert.assertEquals("eee", padding(3, 'e'));

        try {
            padding(-2, 'e');
            Assert.fail("Expected IndexOutOfBoundsException");
        } catch (IndexOutOfBoundsException e) {
            Assert.assertTrue(e.getMessage().contains("Cannot pad a negative amount:"));
        }
    }

