Function:
public class Multiple {
int[][] multiple(int size) {
        int[][] table = new int[size][size];
        for (int axisI = 0; axisI < size; axisI++) {
            for (int axisJ = 0; axisJ < size; axisJ++) {
                table[axisI][axisJ] = (axisI + 1) * (axisJ + 1);
            }
        }
        return table;
    }
}

