Function:
public class LongToBytes {
public static byte[] longToBytes(long l) {
        int longSize = Long.BYTES;
        byte[] result = new byte[longSize];
        for (int i = longSize - 1; i >= 0; i--) {
            result[i] = (byte) (l & 0xFF);
            l >>= longSize;
        }
        return result;
    }
}

