public class Any {
public static long any(long l) {
		l = l | (l << 32) | (l >>> 32);
		l = l | (l << 16) | (l >>> 16);
		l = l | (l << 8) | (l >>> 8);
		l = l | (l << 4) | (l >>> 4);
		l = l | (l << 2) | (l >>> 2);
		l = l | (l << 1) | (l >>> 1);
		return l;
	}
}

