    public void testCeil() {
        assertEquals(0, ceil(0, 16));
        assertEquals(16, ceil(1, 16));
        assertEquals(16, ceil(15, 16));
        assertEquals(16, ceil(16, 16));
        assertEquals(32, ceil(17, 16));
        assertEquals(-16, ceil(-1, 16));
        assertEquals(-16, ceil(-15, 16));
        assertEquals(-16, ceil(-16, 16));
        assertEquals(-32, ceil(-17, 16));
    }

