    assertNotEquals(1.0d, NumberHelper.round(0.49d, 1), 0.0d);
    assertEquals(1.0f, NumberHelper.round(1.2f, 0), 0.01f);
    assertEquals(1.2f, NumberHelper.round(1.22f, 1), 0.001f);
    assertEquals(-1.0f, NumberHelper.round(-1.2f, 0), 0.01f);
    assertEquals(-1.2f, NumberHelper.round(-1.22f, 1), 0.001f);
  }

Function:
public class CalculateRequests {
static int calculateRequests(int cpuLoad, int limit, int maxRequests) {

        // Validations
        if (cpuLoad < limit) {
            return maxRequests;
        }
        if (limit == 100) {
            // do not throttle in this case
            return maxRequests;
        }

        double fillLevel = (100.0 - cpuLoad) / (100.0 - limit);
        return (int) Math.round(fillLevel * maxRequests);

    }
}

