public class MinimumDifference {
public static double minimumDifference(double a, double b) {
		double diffAngle = b - a;
		if (diffAngle > 180)
			diffAngle -= 360;
		else if (diffAngle < -180)
			diffAngle += 360;
		return diffAngle;
	}
}

