        assertEquals(45, GeoUtils.normalizeLatitude(45), 0);
        assertEquals(90, GeoUtils.normalizeLatitude(95), 0);
        assertEquals(-90, GeoUtils.normalizeLatitude(-95), 0);
    }

Function:
public class NormalizeLongitude {
public static double normalizeLongitude(double lng) {
        double result = lng;
        while (result < -180) {
            result += 360;
        }
        while (result > 180) {
            result -= 360;
        }
        return result;
    }
}

