public class To32Bits {
public static byte[] to32Bits(int i) {
      byte[] bytes = new byte[4];
      bytes[0] = (byte)((0xFF000000 & i) >> 24);
      bytes[1] = (byte)((0x00FF0000 & i) >> 16);
      bytes[2] = (byte)((0x0000FF00 & i) >> 8);
      bytes[3] = (byte)((0x000000FF & i));
      return bytes;
   }
}

