public class GetCNWeek {
public static String getCNWeek(int week) {
		String str_week = "";
		switch (week) {
			case 1 :
				str_week = "星期一";
				break;
			case 2 :
				str_week = "星期二";
				break;
			case 3 :
				str_week = "星期三";
				break;
			case 4 :
				str_week = "星期四";
				break;
			case 5 :
				str_week = "星期五";
				break;
			case 6 :
				str_week = "星期六";
				break;
			case 7 :
				str_week = "星期日";
				break;
		}
		return str_week;
	}
}

