Function:
public class CreateFloat {
static double createFloat(boolean sign, long mantissa, int exp) {
		exp += 1023;
		long bits = mantissa >>> 11;
		if (exp == 0) {
			bits = bits >> 1;
		}
		else {
			bits = bits & 0xfffffffffffffL;
		}
		bits |= (long) exp << 52;

		if (sign) {
			bits |= 0x8000000000000000L;
		}
		return Double.longBitsToDouble(bits);
	}
}

