		Assert.assertEquals(x, y, 0);

		x = -4.5;
		data = FloatFormat.extractExpSig(x);
		y = FloatFormat.createFloat(data.sign, data.mantisa, data.exp);
		Assert.assertEquals(x, y, 0);

		x = 0.00000000000000000000000045;
		data = FloatFormat.extractExpSig(x);
		y = FloatFormat.createFloat(data.sign, data.mantisa, data.exp);
		Assert.assertEquals(x, y, 0);

		x = -0.000000000000000000000000045;
		data = FloatFormat.extractExpSig(x);
		y = FloatFormat.createFloat(data.sign, data.mantisa, data.exp);
		Assert.assertEquals(x, y, 0);
	}

