public class Clamp {
public static double clamp(double d) {
        return Math.min(Math.max(d, -1), 1);
    }
}

Test Case:
@Test
    void clamp() {
        // Upper and lower bounds work normally
        assertEquals(MathUtil.clamp(1.25), 1.0);
        assertEquals(MathUtil.clamp(-5.5), -1.0);

        // Works for large and infinite numbers
        assertEquals(MathUtil.clamp(Double.MAX_VALUE), 1.0);
        assertEquals(MathUtil.clamp(Double.NEGATIVE_INFINITY), -1.0);

        // Doesn't change values in range
        assertEquals(MathUtil.clamp(0.10118304), 0.10118304);
        assertEquals(MathUtil.clamp(-0.8572), -0.8572);
    }

Function:
public class DeadZone {
public static double deadZone(double control, double deadZone) {
        return Math.abs(control) > deadZone ? control : 0;
    }
}

Test Case:
@Test
    void deadZone() {
        // Ensure we don't cut off things above the deadzone
        assertEquals(MecanumUtil.deadZone(1.0, 0.5), 1.0);
        assertEquals(MecanumUtil.deadZone(0.8, 0.5), 0.8);
        assertEquals(MecanumUtil.deadZone(-0.6, 0.5), -0.6);

        // If it's right on the edge, we should hit the deadzone
        assertEquals(MecanumUtil.deadZone(0.5, 0.5), 0.0);
        assertEquals(MecanumUtil.deadZone(-0.5, 0.5), 0.0);

        // If it's under, we should hit the deadzone as well
        assertEquals(MecanumUtil.deadZone(0.2, 0.5), 0.0);
        assertEquals(MecanumUtil.deadZone(0.0, 0.5), 0.0);
        assertEquals(MecanumUtil.deadZone(-0.3, 0.5), 0.0);
    }

