public class Long2ip {
public static String long2ip(long ipLong) {
        long o4 = (ipLong >> 24) & 0xFF;
        long o3 = (ipLong >> 16) & 0xFF;
        long o2 = (ipLong >> 8) & 0xFF;
        long o1 = (ipLong >> 0) & 0xFF;
        return String.format("%d.%d.%d.%d", o4, o3, o2, o1);
    }
}

