Function:
public class IntToIp {
public static String intToIp(int i) {
        StringBuilder out = new StringBuilder(15);
        out.append((i >> 24) & 0xFF);
        out.append(".");
        out.append((i >> 16) & 0xFF);
        out.append(".");
        out.append((i >> 8) & 0xFF);
        out.append(".");
        out.append(i & 0xFF);

        return out.toString();
    }
}

