        Assert.assertEquals(15.0, Position.getBearingDifferenceDegrees(20, 5), precision);
        Assert.assertEquals(15.0, Position.getBearingDifferenceDegrees(380, 5), precision);
        Assert.assertEquals(-25, Position.getBearingDifferenceDegrees(-20, 5), precision);
        Assert.assertEquals(5, Position.getBearingDifferenceDegrees(-20, -25), precision);
    }

