Function:
public class Fibo {
public static int fibo(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        if (n <= 1) {
            return n;
        }
        return fibo(n - 1) + fibo(n - 2);
    }
}

