    public void testFibException() {
        assumeThat(expectedException).isNotNull();
        assertWhen((p) -> Fibo.fibo(p), x).throwException(
                instanceOf(expectedException));
    }

Function:
public class GetRelativeHeight {
protected int getRelativeHeight(int givenValue, int maxValue, int maxHeight) {
        try {
            return (maxHeight * givenValue) / maxValue;
        } catch (Exception e) {
            return 0;
        }
    }
}

