        double d = 10.456;
        assertEquals(3, (int) CommonUtil.determinePriceCatForCPD(d));
        d = 005D;
        assertEquals(2, (int) CommonUtil.determinePriceCatForCPD(d));
        d = 0.69999999999999;
        assertEquals(1, (int) CommonUtil.determinePriceCatForCPD(d));
        d = 7.123456789;
        assertEquals(3, (int) CommonUtil.determinePriceCatForCPD(d));
        d = -1D;
        assertEquals(3, (int) CommonUtil.determinePriceCatForCPD(d));
        d = 1.9633331;
        assertEquals(1, (int) CommonUtil.determinePriceCatForCPD(d));
    }

