			0,2,2,
			0,3,3,
			0,4,4,
		};

		ret = OutputHelper.flipSecondScanline(buffer, 3, 8);
		assertEquals(0, ret[0]);
		assertEquals(3, ret[3]);
		assertEquals(2, ret[4]);
		assertEquals(1, ret[5]);
		assertEquals(4, ret[6]);
	}

