Function:
public class ComputeTargetQui {
public static double computeTargetQui(boolean implicit, double value, double currentValue) {
    // We want Qui to change based on value. What's the target value, Qui'?
    if (implicit) {
      // Target is really 1, or 0, depending on whether value is positive or negative.
      // This wouldn't account for the strength though. Instead the target is a function
      // of the current value and strength. If the current value is c, and value is positive
      // then the target is somewhere between c and 1 depending on the strength. If current
      // value is already >= 1, there's no effect. Similarly for negative values.
      if (value > 0.0f && currentValue < 1.0) {
        double diff = 1.0 - Math.max(0.0, currentValue);
        return currentValue + (value / (1.0 + value)) * diff;
      }
      if (value < 0.0f && currentValue > 0.0) {
        double diff = -Math.min(1.0, currentValue);
        return currentValue + (value / (value - 1.0)) * diff;
      }
      // No change
      return Double.NaN;
    } else {
      // Non-implicit -- value is supposed to be the new value
      return value;
    }
  }
}

Test Case:
@Test
  public void testImplicitQui() {
    assertNaN(ALSUtils.computeTargetQui(true, 0.0, 1.0));
    assertNaN(ALSUtils.computeTargetQui(true, 0.0, 0.0));
    assertNaN(ALSUtils.computeTargetQui(true, 0.0, -1.0));
    assertNaN(ALSUtils.computeTargetQui(true, 0.5, 1.0));
    assertNaN(ALSUtils.computeTargetQui(true, -0.5, 0.0));
    assertEquals(0.75, ALSUtils.computeTargetQui(true, 1.0, 0.5));
    assertEquals(0.25, ALSUtils.computeTargetQui(true, -1.0, 0.5));
    for (double d : new double[] { -1.0 , 0.0, 0.5, 1.0, 2.0 }) {
      assertEquals(d, ALSUtils.computeTargetQui(false, d, 0.0));
    }
  }

Function:
public class PermissionsToUmask {
public static int permissionsToUmask(int permissions) {
    // the umask contains exactly the bits that the permissions don't have
    return permissions ^ 0777; // note this is octal
  }
}

Test Case:
@Test
  public void testPermissionsToUmask() {
    Assert.assertEquals(0000, FileUtils.permissionsToUmask(0777));
    Assert.assertEquals(0022, FileUtils.permissionsToUmask(0755));
    Assert.assertEquals(0002, FileUtils.permissionsToUmask(0775));
    Assert.assertEquals(0137, FileUtils.permissionsToUmask(0640));
    Assert.assertEquals(0077, FileUtils.permissionsToUmask(0700));
    Assert.assertEquals(0777, FileUtils.permissionsToUmask(0000));

    Assert.assertEquals("000", FileUtils.permissionsToUmask("777"));
    Assert.assertEquals("022", FileUtils.permissionsToUmask("755"));
    Assert.assertEquals("002", FileUtils.permissionsToUmask("775"));
    Assert.assertEquals("137", FileUtils.permissionsToUmask("640"));
    Assert.assertEquals("077", FileUtils.permissionsToUmask("700"));
    Assert.assertEquals("777", FileUtils.permissionsToUmask("000"));

    Assert.assertEquals("000", FileUtils.permissionsToUmask("rwxrwxrwx"));
    Assert.assertEquals("022", FileUtils.permissionsToUmask("rwxr-xr-x"));
    Assert.assertEquals("002", FileUtils.permissionsToUmask("rwxrwxr-x"));
    Assert.assertEquals("137", FileUtils.permissionsToUmask("rw-r-----"));
    Assert.assertEquals("077", FileUtils.permissionsToUmask("rwx------"));
    Assert.assertEquals("777", FileUtils.permissionsToUmask("---------"));
  }

