Function:
public class Round {
public static int round(int value, int step) {
		int roundDownOrUp = (int) Math.round(((double) (value % step)) / step);
		int result = ((int) (value / step)) * step;
		if (roundDownOrUp != 0)
			result += roundDownOrUp * step;
		return result;
	}
}

