public class GetSplit {
public static int[] getSplit(int docId) {
        if (docId <= 0) {
            throw new IllegalArgumentException("docId must be positive");
        }
        int[] ret = new int[3];
        ret[0] = docId / 1000000;
        ret[1] = (docId % 1000000) / 1000;
        ret[2] = docId % 1000;
        return ret;
    }
}

