		String actual = Matrix.GRID(2, 2);		
		Assert.assertEquals("L",actual);

		actual = Matrix.GRID(3, 3);		
		Assert.assertEquals("R",actual);
	}

Function:
public class SpiralMatrix {
static int[][] SpiralMatrix(int n) {
		int[][] a = new int[n][n];
		int c = 1, x = 0, y = 0;
		int d = 0;
		while (c <= n * n) {
			if (a[x][y] == 0) {
				a[x][y] = c++;

			} else {
				d++;
				d = d % 4;
			}

			switch (d) {
			case 0:
				if (y < n - 1 && a[x][y + 1] < 1)
					y++;
				else {
					d = 1;
					x++;
				}
				break;

			case 1:
				if (x < n - 1 && a[x + 1][y] < 1)
					x++;
				else {
					y--;
					d = 2;
				}
				break;

			case 2:
				if (y > 0 && a[x][y - 1] < 1) {
					y--;
				} else {
					x--;
					d = 3;
				}
				break;
			case 3:
				if (x > 0 && a[x - 1][y] < 1) {
					x--;
				} else {
					y++;
					d = 0;
				}
				break;
			default:
				break;
			}

		}
		return a;
	}
}

Test Case:
