public class GetMultiplier {
public long getMultiplier(char multiplierChar) {
    long multiplier = 1;
    multiplierChar = Character.toLowerCase(multiplierChar);
    switch (multiplierChar) {
      case 't':
        multiplier = multiplier * 1024;
      case 'g':
        multiplier = multiplier * 1024;
      case 'm':
        multiplier = multiplier * 1024;
      case 'k':
        multiplier = multiplier * 1024;
        break;
    }
    return multiplier;
  }
}

