        double result = MathUtil.getCumulativeMovingAverage(oldAvg, oldCount, newValue);
        assertEquals(expResult, result, 0.00000001);
        oldAvg = result;
        oldCount++;
        newValue = 16.0;
        expResult = 13.0;
        result = MathUtil.getCumulativeMovingAverage(oldAvg, oldCount, newValue);
        assertEquals(expResult, result, 0.00000001);
        oldAvg = result;
        oldCount++;
        newValue = 16.0;
        expResult = 14.0;
        result = MathUtil.getCumulativeMovingAverage(oldAvg, oldCount, newValue);
        assertEquals(expResult, result, 0.00000001);
        oldAvg = result;
        oldCount++;
        newValue = 6.0;
        expResult = 12.0;
        result = MathUtil.getCumulativeMovingAverage(oldAvg, oldCount, newValue);
        assertEquals(expResult, result, 0.00000001);
    }

