Function:
public class Encode {
static public byte[] encode(int c) {
    if (c < 0x80)
      return new byte[] { (byte)c };
    byte[] buf;
    if (c < 0x800) {
      buf = new byte[2];
      buf[0] = (byte)((c >> 6) | (0x80 | 0x40));
    }
    else if (c < 0x10000) {
      buf = new byte[3];
      buf[0] = (byte)((c >> (2 * 6)) | (0x80 | 0x40 | 0x20));
    }
    else {
      buf = new byte[4];
      buf[0] = (byte)((c >> (3 * 6)) | (0x80 | 0x40 | 0x20 | 0x10));
    }
    for (int i = buf.length - 1; i > 0; i--) {
      buf[i] = (byte)((c & 0x3F) | 0x80);
      c >>= 6;
    }
    return buf;
  }
}

Test Case:
@Test
  public void testEncode() throws UnsupportedEncodingException {
    for (int i = 0; i < 0x10FFFF; i++) {
      if (Utf16.isSurrogate(i))
        continue;
      char[] chars;
      if (i <= 0xFFFF)
        chars = new char[] { (char)i };
      else
      chars = new char[] { Utf16.surrogate1(i), Utf16.surrogate2(i) };
      Assert.assertEquals(Utf8.encode(i), new String(chars).getBytes("UTF-8"));
    }
  }

Function:
public class ConvertBase {
public static String convertBase(int number, int base) {
    // special case
    if (number == 0)
      return "0";

    if (base > 62)
      throw new IllegalArgumentException("base must be 62 or less: base=" + base);
    if (base <= 0)
      throw new IllegalArgumentException("base must be greater than zero: base=" + base);

    StringBuffer conversion = new StringBuffer();

    if (base == 1) {
      for (int i = 0; i < number; i++)
        conversion.append("1");
      return conversion.toString();
    }

    String digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    while (number > 0) {
      int digitIndex = number % base;
      conversion.insert(0, digits.charAt(digitIndex));
      number = number / base;
    }
    return conversion.toString();
  }
}

