Function:
public class AddToAverage {
public static double addToAverage(double oldCount,
                                      double oldAverage,
                                      double newCount,
                                      double newTotalTime) {
        if (newCount==0) {
            return oldAverage;
        }
        double newAverage = newTotalTime / newCount;
        return
            ((oldCount) / (newCount + oldCount) * oldAverage) +
                (newCount / (newCount + oldCount) * newAverage);
    }
}

