public class LongToBytes {
protected static byte[] longToBytes(long initialState) {
		byte[] b = new byte[8];
		for(int i = 0; i < 8; i++) {
			b[7 - i] = (byte) (initialState >>> (i * 8));
		}
		return b;
	}
}

