      assertEquals(PluginUtils.hexDigitToInt(Character.toUpperCase(HEX_DIGIT[i])), i);
    }
    assertEquals(PluginUtils.hexDigitToInt('x'), -1);
    assertEquals(PluginUtils.hexDigitToInt('Y'), -1);
    assertEquals(PluginUtils.hexDigitToInt('-'), -1);
  }

Function:
public class BinomialCoeff {
public static long binomialCoeff(int n, int k) {
    if (n <= k) {
      return 1;
    }
    int c;
    if (k > n - k) { // take advantage of symmetry
      k = n - k;
    }
    c = 1;
    for (int i = 0; i < k; i++) {
      c *= (n - i);
      c /= (i + 1);

    }
    return c;
  }
}

Test Case:
@Test
  public void testBinomialCoeff() throws Exception {
    // choose(7, 3) = 35
    long result = MathUtils.binomialCoeff(7, 3);
    assertEquals(35, result);

    // Check when k > n-k
    // choose(5,3) = 10
    result = MathUtils.binomialCoeff(5, 3);
    assertEquals(result, 10);
  }

