public class AddDigits {
static int addDigits(int num) {
        if (num < 10) return num;
        int i, count = 0;
        while ((i = num % 10) != 0 || num >= 10) {
            count += i;
            num -= i;
            num /= 10;
        }
        return addDigits(count);
    }
}

