public class CountBitsWisdom {
static int[] countBitsWisdom(int num) {
        if (num < 0) return null;

        int[] f = new int[num + 1];
        //0, 1, 1, 2, 1, 2
        for (int i = 1; i <= num; i++) f[i] = f[i >> 1] + (i & 1);
        return f;
    }
}

