Function:
public class Sum {
static int sum(int a, int b) {
        if (a == 0) return b;
        if (b == 0) return a;
        int temp;
        while (b != 0) {
            temp = a & b;
            a = a ^ b;
            b = temp << 1;
        }
        return a;
    }
}

