Function:
public class CalculateScore {
public static float calculateScore(int value, int benchmark) {
    if (value <= benchmark) {
      return 100f;
    } else if (value <= 4f * benchmark) {
      return (((-1f / (3f * benchmark)) * value) + (4f / 3f)) * 100f;
    } else {
      return 0;
    }
  }
}

