		// single boundary in common
		Rect r3 = new Rect(-1000000, 0, 45000000, 55000000);
		// inclusion
		Rect r4 = new Rect(-1000000, 2000000, 45000000, 55000000);
		// outside
		Rect r5 = new Rect(0, 1000000, 55000000, 56000000);

