Function:
public class ToBytes {
public static byte[] toBytes(long value) {

    long v = value;
    byte[] bytes = new byte[8];
    for (int i = 7; i >= 0; i--) {
      bytes[i] = (byte) v;
      v >>= 8;
    }
    return bytes;
  }
}

