Function:
public class Hue {
static float hue(int i, int maxDomains)
    {
        float colorDistance = 1f / (float) Math.ceil((maxDomains + 2) / 2f) / 2f;
        return i % 2 == 0
                ? 21f / 360f + (i / 2 + 1) * colorDistance
                : 201f / 360f + (float) Math.ceil(i / 2f) * colorDistance;
    }
}

