        assertEquals(180.0, lons[1], 0.0);

        lons = GaussianGridConfig.computeLongitudePoints(360);
        assertEquals(360, lons.length);
        assertEquals(0.0, lons[0], 0.0);
        assertEquals(179.0, lons[179], 0.0);
