Function:
public class Norm {
public static short norm(int var1) throws ArithmeticException
    {
    	if(var1==0)
    		throw new ArithmeticException("Value can not be 0");

    	int currValue=var1;    	
    	if(var1<0)
    	{
    		if(var1<=0xC0000000)
    			return 0;

    		currValue=~(var1-1);
    	}

    	short count=-1;
    	//check 16 bits sequence
    	if(currValue>>16!=0)
    		currValue=currValue>>16;
    	else
    		count+=16;

    	//check 8 bits sequence
    	if(currValue>>8!=0)
    		currValue=currValue>>8;
    	else
    		count+=8;

    	//check 4 bits sequence
    	if(currValue>>4!=0)
    		currValue=currValue>>4;
    	else
    		count+=4;

    	//check 2 bits sequence
    	if(currValue>>2!=0)
    		currValue=currValue>>2;
    	else
    		count+=2;

    	//check 1 bits sequence
    	if(currValue>>1==0)
    		count+=1;

    	return count;
    }
}

Test Case:
@Test
    public void testNorm() {    
    	//positive values
    	assertEquals(0, BasicFunctions.norm(0x40000000));

        assertEquals(8, BasicFunctions.norm(0x00400000));

        assertEquals(17, BasicFunctions.norm(0x00002000));

        assertEquals(26, BasicFunctions.norm(0x00000010));

        //negative values
        assertEquals(2, BasicFunctions.norm(0xF0000000));

        assertEquals(7, BasicFunctions.norm(0xFF800000));

        assertEquals(16, BasicFunctions.norm(0xFFFFC000));

        assertEquals(25, BasicFunctions.norm(0xFFFFFFE0));
    }

