public class Calculate {
public static short calculate(short crcValue, byte data) {
      short x = (short) (((crcValue >>> 8) ^ data) & 0xff);
      x ^= (x >>> 4);
      return (short) ((crcValue << 8) ^ (x << 12) ^ (x << 5) ^ x);
    }
}

