Function:
public class Base64SizeInBytes {
static int base64SizeInBytes(int sizeInBytes) {
    int result = sizeInBytes * 4 / 3;
    int remainder = sizeInBytes * 4 % 3;
    return remainder == 0 ? result : result + (4 - remainder);
  }
}

