Function:
public class CheckLevelRestrictionsActive {
public static boolean checkLevelRestrictionsActive(int playerLevel, int activeAmount){
		switch (activeAmount){
			case 0:
			case 1:
			case 2:
				return true;
			case 3:
			case 4:
			case 5:
				return playerLevel >= activeAmount * activeAmount - (5 - activeAmount);
			default:
				return false;
