        assertEquals("The returned decimal is not correct.",
                "-22704862.599000000", decimal);
    }

Function:
public class InterpretOrdinal {
static int interpretOrdinal(int ordinal, int numTiers) {
    if (ordinal >= 0) {
      return Math.min(ordinal, numTiers - 1);
    }
    return Math.max(numTiers + ordinal, 0);
  }
}

