public class MaxUnsigned {
public static int maxUnsigned(int numBits) {
		if (numBits > 32) {
			throw new IllegalArgumentException("integer overflow");
		}
		if (numBits == 0) return 0;
		if (numBits == 32) return 0xffffffff;
		return (0b1 << (numBits)) -1;
	}
}

