public class GetMaxBitIndex {
public static int getMaxBitIndex(int number) {
    if (number < 0) {
      throw new RuntimeException("negative numbers unsupported");
    }
    int maxBit = 0;
    while((number = number >>> 1) >=0) {
      maxBit++;
      if (number == 0) {
        break;
      }
    }    
    return maxBit;

  }
}

