Function:
public class LoopOne {
static int loopOne(int num) {
    if (num <= 0) {
      return 0;
    }
    if (num == 1) {
      return 1;
    }

    int pre = 1;
    int cur = 1;

    for (int i = 0; i < num - 2; i++) {
      int temp = pre;
      pre = cur;
      cur = temp + cur;
    }

    return cur;
  }
}

