public class RecursiveOne {
static int recursiveOne(int num) {
//    System.out.println("run");
    if (num < 0) {
      return 0;
    }

    if (num == 1) {
      return 1;
    }

    return recursiveOne(num - 1) + recursiveOne(num - 2);
  }
}

