public class GeneralTermFormula {
static int generalTermFormula(int num) {
    double temp = Math.sqrt(5);
    return (int) (1 / temp * (Math.pow((1 + temp) / 2, num) - Math.pow((1 - temp) / 2, num)));
  }
}

