Function:
public class Triangle {
public static int triangle(int a, int b, int c) {
        if (a <= 0 || b <= 0 || c <= 0) {
            return 0;
        }

        // If sum of any two edges is greater than the length of the third edge
        if (a == b && b == c) {
            return 1;
        } else if (a + b > c && b + c > a && a + c > b) {
            return 2;
        }
        return 0;
    }
}

Test Case:
@Test
    public void testTriangle() {
        Map<int[], Integer> mapIO = new HashMap<int[], Integer>() {{
            put(new int[]{3, 3, 3}, 1);
            put(new int[]{3, 5, 4}, 2);
        }};

        for (Map.Entry<int[], Integer> io : mapIO.entrySet()) {
            int[] i = io.getKey();
            int ret = Triangle.triangle(i[0], i[1], i[2]);
            Assert.assertEquals(io.getValue().intValue(), ret);
        }
    }

Function:
public class GetNextRepairTime {
public static long getNextRepairTime(long delayStartTime, long coolOffPeriod, double exponentialFactor, long repairRetriesCountSinceDelay, long repairRetriesMaxPeriod) {
		long max = Math.min(repairRetriesCountSinceDelay + 1, (long) Math.ceil((Math.log(1 + repairRetriesMaxPeriod  / coolOffPeriod) / Math.log(exponentialFactor))));
		return (long) (delayStartTime + (coolOffPeriod * (Math.pow(exponentialFactor, max) - 1)));
	}
}

